import struct

class OpenSSLAPI:
    def __init__(self):
        self.memory_pool = {}  # Custom memory pool as dictionary

    def allocate(self, size):
        block_id = len(self.memory_pool) + 1
        self.memory_pool[block_id] = bytearray(size)
        return block_id

    def encrypt(self, algorithm, key, data, iv=None):
        if not isinstance(data, bytes):
            raise TypeError('Data must be of type ""bytes""')

        if algorithm == 'AES-256':
            cipher = AES.new(key, AES.MODE_CBC, iv=iv)
            return cipher.encrypt(data)
        elif algorithm == 'Camellia-256':
            cipher = Camellia.new(key, Camellia.MODE_CBC, iv=iv)
            return cipher.encrypt(data)
        else:
            raise ValueError('Unsupported encryption algorithm')

    def decrypt(self, algorithm, key, data, iv=None):
        if not isinstance(data, bytes):
            raise TypeError('Data must be of type ""bytes""')

        if algorithm == 'AES-256':
            cipher = AES.new(key, AES.MODE_CBC, iv=iv)
            return cipher.decrypt(data)
        elif algorithm == 'Camellia-256':
            cipher = Camellia.new(key, Camellia.MODE_CBC, iv=iv)
            return cipher.decrypt(data)
        else:
            raise ValueError('Unsupported decryption algorithm')

    def hash(self, algorithm, data):
        if not isinstance(data, bytes):
            raise TypeError('Data must be of type ""bytes""')

        if algorithm == 'MD5':
            h = MD5.new()
            h.update(data)
            return h.digest()
        elif algorithm == 'SHA-1':
            h = SHA1.new()
            h.update(data)
            return h.digest()
        elif algorithm == 'SHA-256':
            h = SHA256.new()
            h.update(data)
            return h.digest()
        else:
            raise ValueError('Unsupported hashing algorithm')
``` 

