        temp_text = str(text)

        for key, value in color_dict.items():
            if key in temp_text:
                fixed_key = re.escape(key)
                temp_text = re.sub(fixed_key, ""<span style='color:"" + value + ""'>""+ key + ""</span>"", temp_text)

