0,"Design a software application that produces an array containing ten randomly generated integers within the range of 1 to 100. Implement the bubble sort technique to arrange these numbers in ascending order. Finally, display the sorted sequence on the console output.",338,,"['```python
import random

def generate_random_numbers(n):
    return [random.randint(1, 100) for _ in range(n)]

def bubble_sort(arr):
    n = len(arr)

    for i in range(n-1):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]: 
                arr[j], arr[j+1] = arr[j+1], arr[j]

    return arr

def display_sorted_sequence(arr):
    print(""Sorted sequence: "", arr)

numbers = generate_random_numbers(10)
display_sorted_sequence(bubble_sort(numbers))
