from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
import base64

class AESCipher:
    def __init__(self, key):
        assert len(key) % 16 == 0

        enc_key = base64.b64encode(get_random_bytes(32)).decode('utf-8')

        iv_nonce_encoded_strng = get_random_bytes(12).hex()

        self.cipher = AES.new(key, AES.MODE_EAX, nonce=bytes.fromhex(iv_nonce_encoded_strng))

    def encrypt(self, data):
        ciphertext, tag = self.cipher.encrypt_and_digest(data)
        return (self.cipher.nonce, ciphertext, tag)

    def decrypt(self, nonce, ciphertext, tag):
