```python
class UserPreferences:
    def __init__(self):
        self.preferences = {}

    def add_preference(self, username, preference):
        if username not in self.preferences:
            self.preferences[username] = []

        self.preferences[username].append(preference)

    def filter_preferences(self, username=None, condition=None):
        # Filter by username and/or condition
        if not condition and not username: 
            return self.preferences
        elif username and condition:
            filtered = {user: [pref for pref in prefs if condition(pref)] for user, prefs in self.preferences.items() if user == username}
        else: 
            if username:
                users = [username]
            else:
                users = list(self.preferences.keys())

            filtered = {user: [pref for pref in prefs if condition(pref)] for user, prefs in self.preferences.items() if user in users}
