network_context_example_contexts_network",680,,"[""Here's the code that you requested:

```python
import random

class NetworkContext:
    def __init__(self, ue_data_rates, priority_levels):
        self.ue_data_rates = ue_data_rates
        self.priority_levels = priority_levels
        self.ue_count = len(ue_data_rates)
        self.total_priority_points = sum(priority_levels)
        self.active_ues = list(range(self.ue_count))

    def calculate_priority_point(self, ue_index):
        return (self.priority_levels[ue_index] / self.total_priority_points) * self.ue_data_rates[ue_index]

class NetworkScheduler:
    def __init__(self, context):
        self.context = context
        self.resource_allocation = {}

    def allocate_resource(self):
        active_ues_with_points = [(i, ue_index, self.context.calculate_priority_point(ue_index)) for i, ue_index in enumerate(self.context.active_ues)]

        for _ in range(len(active_ues_with_points)):
            max_point_uindex = max(active_ues_with_points, key=lambda x:x[2])[1]
            active_ues_with_points.remove((max_point_uindex, _, max_point))

            if max_point_uindex not in self.resource_allocation:
                self.resource_allocation[max_point_uindex] = 1
            else:
                self.resource_allocation[max_point_uindex] += 1

            for point in active_ues_with_points:
                if point[2] < max_point:
                    point[2] *= 0.95

def calculate_qos(context):
    qos_list = []

    for index in range(context.ue_count):
        data_rate_factor = context.ue_data_rates[index]

        if index in context.active_ues:
            congestion_factor = 1 - (random.uniform(0.05, 0.2))

            if index in network_scheduler.resource_allocation and network_scheduler.resource_allocation[index] > 1:
                priority_factor = (context.priority_levels[index] / context.total_priority_points) ** 2
            else:
                priority_factor = context.priority_levels[index]

            qos_list.append(data_rate_factor * congestion_factor * priority_factor)

    return qos_list
```
You can then create a NetworkContext and call `allocate_resource` method on it:

```python
network_context = NetworkContext([3000, 4500, 6750], [20, 35, 45])
network_scheduler = NetworkScheduler(network_context)
network_scheduler.allocate_resource()
```
And calculate QoS:

```python
calculate_qos(network_context)
```
