```python
import random

class GraphAnalyzer:
    def __init__(self, graph):
        self.graph = graph

    def _is_triangle(self, vertex1, vertex2, vertex3):
        return vertex1 in self.graph[vertex2] and vertex2 in self.graph[vertex3] and vertex3 in self.graph[vertex1]

    def calculate_average_clustering_coefficient(self):
        triangles = 0
        connected_triplets = 0
        for vertex in self.graph:
            for other_vertex in self.graph[vertex]:
                for common_vertex in self.graph[other_vertex]:
                    if common_vertex != vertex and common_vertex != other_vertex:
                        if self._is_triangle(vertex, other_vertex, common_vertex):
                            triangles += 1
                        connected_triplets += 1

        average_clustering_coefficient = (3 * triangles) / connected_triplets if connected_triplets > 0 else 0.0
        return average_clustering_coefficient

def generate_random_graph(n):
    graph = {i: set() for i in range(n)}
    edges = set()
    while len(edges) < n:
        u, v = random.sample(range(n), 2)
        if u != v and (u, v) not in edges and (v, u) not in edges:
            graph[u].add(v)
            graph[v].add(u)
            edges.add((u, v))
    return graph

def main():
    n_vertices = 10
    random_graph = generate_random_graph(n_vertices)

    analyzer = GraphAnalyzer(random_graph)

    avg_clustering_coefficient = analyzer.calculate_average_clustering_coefficient()

    print(f""Average Clustering Coefficient of the generated graph: {avg_clustering_coefficient:.4f}"")

if __name__ == ""__main__"":
    main()
``` 

This script generates a random graph, calculates its average clustering coefficient and prints it. The `GraphAnalyzer` class implements methods to analyze the graph structure and calculate properties such as average clustering coefficient. The random graph generator uses simple edge addition approach to create a random network with given number of vertices and edges. The main function demonstrates how these components work together.
