```python
import timeit
import psutil
import random
import string
from memory_profiler import profile

class CodeSpeedEvaluator:
    def __init__(self, min_time=0.1, max_time=5):
        self.min_time = min_time
        self.max_time = max_time

    @staticmethod
    def GenerateRandomCode():
        return ''.join(random.choices(string.ascii_uppercase + string.digits, k=random.randint(50, 100)))

    @staticmethod
    def GenerateFixedCode():
        return 'a'* random.randint(50, 100)

    def __str__(self):
        return f""Time range: {self.min_time} to {self.max_time}""

    @profile
    def MeasureExecutionPerformance(self, codeSnippet):
        executionTime = timeit.repeat(stmt=codeSnippet, repeat = 5, number = 10)
        averageExecutionTime = sum(executionTime) / len(executionTime)

        process = psutil.Process()
        memoryInfo = process.memory_info().rss # Resident Set Size: The non-swapped physical memory a process has used

        print(f""Average execution time of code snippet: {averageExecutionTime} seconds"")
        print(f""Memory usage of code snippet: {memoryInfo/1024} kilobytes."")
```
