class CommandLineExecutor:
    def __init__(self):
        self.commands = {
            '--manpage': self.display_usage,
            '-cs': self.count_and_show,
            '-o': self.output_to_file
        }

    @staticmethod
    def parse_arguments():
        args = sys.argv[1:]
        if not args:
            return None, []

        command = args[0]
        arguments = args[1:]
        return command, arguments

    def handle_command(self):
        command, arguments = self.parse_arguments()

        if command in self.commands:
            function = self.commands[command]
            function(*arguments)
        else:
            self.display_usage()

    @staticmethod
    def display_usage():
        print(""Usage: scriptname [options]"")
        print(""Options:"")
        print(""--manpage : Display this manual page."")
        print(""-cs       : Count and show the number of lines in a file."")
        print(""-o <file> : Output to specified file."")

