def enhanced_filter_even_numbers(numbers, include_odd_indices=False):
    try:
        if not isinstance(numbers, list):
            raise ValueError(""Input must be a list."")

        if not isinstance(include_odd_indices, bool):
            raise TypeError(""include_odd_indices must be a boolean value."")

        for num in numbers:
            if not isinstance(num, int):
                raise ValueError(""All elements in the input must be integers."")

        result = []

        for idx, num in enumerate(numbers):
            if (idx % 2 == 0 and include_odd_indices) or (idx % 2 != 0 and not include_odd_indices):
                result.append(num)

        return result

    except ValueError as e:
        return str(e)

    except TypeError as e:
        return str(e)
