```python
import time
import random

class NetworkLogEntry():
    def __init__(self, timestamp, event_type):
        self.timestamp = int(timestamp)
        self.event_type = event_type
        if event_type & 1 == 0:
            self.severity_level = ""Critical""
        else:
            self.severity_level = ""Non-critical""

    def __str__(self):
        return f'Timestamp: {self.timestamp}, Event Type: {self.event_type}, Severity Level: {self.severity_level}'

def create_NetworkLogEntries(numEntries):
    if numEntries <= 0:
        print('Error: count must be greater than zero')
        return []

    log_entries = [None] * numEntries
    for i in range(numEntries):
        current_time = int(time.time())
        event_type = random.randint(1, 10)
        log_entries[i] = NetworkLogEntry(current_time, event_type)

    return log_entries

def main():
    numEntries = 10
    entries = create_NetworkLogEntries(numEntries)
    for entry in entries:
        print(entry)

main()
```
