```python
import hashlib
import os

def calculate_file_sha256(file_path):
    sha256_hash = hashlib.sha256()
    block_size = 4096
    with open(file_path, 'rb') as file:
        while chunk := file.read(block_size):
            sha256_hash.update(chunk)
    return sha256_hash.hexdigest()

def verify_sha256(file_path, expected_hash):
    calculated_hash = calculate_file_sha256(file_path)
    if calculated_hash == expected_hash:
        print(f""SHA-256 hash of {file_path} matches the expected value."")
    else:
        print(f""SHA-256 hash of {file_path} does not match the expected value."")

def process_files(directory, extension='.txt'):
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith(extension):
                full_file_path = os.path.join(root, file)
                print(f""Calculating SHA-256 for: {full_file_path}"")
                verify_sha256(full_file_path, ""expected_value_here"")

# Example usage
directory_to_process = ""/path/to/directory""
process_files(directory_to_process)
