def batch_md5_hash(file_paths: List[str], include_text_files_only: bool = False) -> Dict[str, str]:
    md5_dict = {}

    for file_path in file_paths:
        try:
            with open(file_path, 'rb') as file:
                md5_obj = hashlib.md5()
                chunk = file.read(8192)
                while chunk:
                    md5_obj.update(chunk)
                    chunk = file.read(8192)
            md5_dict[file_path] = md5_obj.hexdigest()
        except FileNotFoundError:
            print(f""File not found: {file_path}"")
        except Exception as e:
            print(f""Error processing {file_path}: {str(e)}"")

    if include_text_files_only:
        return {path: digest for path, digest in md5_dict.items() if is_text_file(path)}

    return md5_dict

def is_text_file(file_path: str) -> bool:
    valid_extensions = ('.txt', '.log', '.csv', '.md', '.json')

    return any(fnmatch(file_path, f'*{ext}') for ext in valid_extensions)

if __name__ == ""__main__"":

