```python
import os
import hashlib
from typing import List, Dict, Tuple
from fnmatch import fnmatch

def batch_md5_hash(file_paths: List[str], include_text_files_only: bool 
= False) -> Dict[str, str]:
    md5_dict = {}

    for file_path in file_paths:
        try:
            with open(file_path, 'rb') as file:
                md5_obj = hashlib.md5()
                chunk = file.read(8192)
                while chunk:
                    md5_obj.update(chunk)
                    chunk = file.read(8192)
            md5_dict[file_path] = md5_obj.hexdigest()
        except FileNotFoundError:
            print(f""File not found: {file_path}"")
        except Exception as e:
            print(f""Error processing {file_path}: {str(e)}"")

    if include_text_files_only:
        return {path: digest for path, digest in md5_dict.items() 
               if is_text_file(path)}

    return md5_dict

def is_text_file(file_path: str) -> bool:
    valid_extensions = ('.txt', '.log', '.csv', '.md', '.json')

    extension_matches = any(fnmatch(file_path, f'*{ext}') for ext in 
                           valid_extensions)

    with open(file_path, 'rb') as f:
        last_block = f.read(8192)[-4:]
        last_byte_check_matches_binary_executable = last_block[-1] == 0x00

    return extension_matches or (last_byte_check_matches_binary_executable and os.path.splitext(file_path)[1] != '.exe')
```
This code is designed to calculate the MD5 hash of multiple files and returns a dictionary containing the hexdigest of the hash for each file. It also has a function that checks if a given file path points to a text or binary executable based on its extension. If the last byte in the read block equals 0x4d, it's considered an exe file, otherwise, it's a binary executable.
