import threading
import logging
from collections import deque

class ConcurrentStack:
    def __init__(self, max_size):
        self.stack = deque([], maxlen=max_size)
        self.lock = threading.Lock()
        self.undo_stack = []
        self.redo_stack = []
        self.max_size = max_size

    def push(self, item):
        with self.lock:
            if len(self.stack) >= self.max_size:
                return ""Error: Stack is full.""
            else:
                self.stack.append(item)
                logging.info(f""Pushed {item} to stack."")
                return True

    def pop(self):
        with self.lock:
            if not self.stack:
                return ""Error: Stack is empty.""
            else:
                item = self.stack.pop()
                logging.info(f""Popped {item} from stack."")
                return item

    def peek(self):
        with self.lock:
            if not self.stack:
                return ""Error: Stack is empty.""
            else:
                return self.stack[-1]

    def size(self):
        with self.lock:
            return len(self.stack)

    def is_empty(self):
        with self.lock:
            return not bool(len(self.stack))

    def undo_push(self, item):
        self.undo_stack.append(item)

    def redo_push(self, item):
        self.redo_stack.append(item)
