```python
import random
import string

class Student():
    def __init__(self, id, name, gpa):
        self.id = id
        self.name = name
        self.gpa = gpa

def generate_students(n):
    students = []
    for i in range(n):
        id = random.randint(1000, 9999) # unique ID between 1000 and 9999
        name = ''.join(random.choices(string.ascii_uppercase + string.ascii_lowercase, k=8)) # random name of length 8
        gpa = round(random.uniform(0.0, 4.0), 2) # GPA between 0.0 and 4.0 rounded to two decimal places
        students.append(Student(id, name, gpa))
    return students

def display_all_students(students):
    for student in students:
        print('ID: {}, Name: {}, GPA: {}'.format(student.id, student.name, student.gpa))

def search_by_id(students, id):
    for student in students:
        if student.id == id:
            return student
    return None

def search_by_name(students, name):
    results = []
    for student in students:
        if student.name == name:
            results.append(student)
    return results
```

