def enhanced_insert_after(start, end, search_str, insert_str, use_manpage=False):
    if not search_str:
        raise ValueError(""Search string cannot be empty"")

    if start >= end:
        raise ValueError(""Start iterator must be before end iterator"")

    case_sensitive = True
    replacements_made = 0
    for i, item in enumerate(start, 1):
        try:
            next_item = next(end)
            if case_sensitive or item.lower() != next_item.lower():
                continue
            if replacements_made >= 2:   # Allow for two replacements per element
                break
            start.insert(i + replacements_made + 1, insert_str)
            replacements_made += 1

            j = i - 1
            while j >= i - min(2, replacements_made) and (case_sensitive or start[j].lower() == search_str.lower()):
                start[j] = insert_str
                j -= 1

                if j < i - min(2, replacements_made):
                    break

            if j < i - min(2, replacements_made) and next_item != end[-1]:
                last_element = next(end)
                while i > j + 1:
                    temp = start[i]
                    start[i] = start[j]
                    start[j] = temp
